#!/usr/bin/env python3
import csv
import json
import sys


def main(argv):
    if len(argv) != 2:
        print("usage: stats.py <chemin.csv>", file=sys.stderr)
        return 2

    path = argv[1]
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            rows = list(csv.reader(f))
    except OSError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    except csv.Error as e:
        print(f"error: {e}", file=sys.stderr)
        return 1

    if not rows:
        print("{}")
        return 0

    header = rows[0]
    columns = {}
    for i, name in enumerate(header):
        columns[name] = [
            row[i].strip() if i < len(row) else ""
            for row in rows[1:]
        ]

    result = {}
    for name, values in columns.items():
        numbers = []
        numeric = True
        for v in values:
            if v == "":
                continue
            try:
                numbers.append(float(v))
            except ValueError:
                numeric = False
                break
        if not numeric or not numbers:
            continue
        result[name] = {
            "count": len(numbers),
            "mean": sum(numbers) / len(numbers),
            "min": min(numbers),
            "max": max(numbers),
        }

    print(json.dumps(result))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

